const INGEST_TIMEOUT_MS = 180_000;
// Keep application context well under DEFAULT_PAYLOAD_CAPACITY (16 KiB).
const MAX_CONTEXT_CHARS = 8_192;
// Personas are short identity/instruction blurbs, not data dumps.
const MAX_PERSONA_CHARS = 2_048;

function boundedText(raw: unknown, limit: number): string {
  if (raw === undefined || raw === null || raw === "") return "";
  let text = typeof raw === "string" ? raw : JSON.stringify(raw);
  if (text.length > limit) {
    text = text.slice(0, limit) + "…[truncated]";
  }
  return text;
}

function normalizeContext(raw: unknown): string {
  return boundedText(raw, MAX_CONTEXT_CHARS);
}

function normalizePersona(raw: unknown): string {
  return boundedText(raw, MAX_PERSONA_CHARS);
}

function ingest(payload: Record<string, unknown>, requestId: string): Promise<any> {
  if (!supervisor) return Promise.reject(new Error("supervisor socket not connected"));
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      if (ingestWaiters.delete(requestId)) {
        reject(new Error(`ingest timed out after ${INGEST_TIMEOUT_MS}ms`));
      }
    }, INGEST_TIMEOUT_MS);
    ingestWaiters.set(requestId, {
      resolve: (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      reject: (error) => {
        clearTimeout(timer);
        reject(error);
      },
    });
    // ControlFrame::Ingest requires author + text. Chat payloads also carry
    // prompt/reply/model for the slot JSON, but text is what the supervisor
    // maps into the llm.complete record's prompt field.
    supervisor!.write(
      encodeFrame({
        type: "INGEST",
        request_id: requestId,
        author: "",
        text: "",
        ...payload,
      })
    );
  });
}

function openDb(): Database {
  const db = new Database(dbPath, { create: true });
  db.exec(`
    CREATE TABLE IF NOT EXISTS app_events (
      id TEXT PRIMARY KEY,
      kind TEXT NOT NULL,
      payload TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);
  for (const table of __RESOURCE_TABLES__) {
    db.exec(`CREATE TABLE IF NOT EXISTS ${table} (
      id TEXT PRIMARY KEY,
      data TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );`);
  }
  return db;
}

